-- Disposable PostgreSQL only: synthetic agreements, injected faults, outer rollback.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.settle_stripe_booking_invoice(jsonb)','execute'),'Anonymous cannot settle invoices');
select ok(not has_function_privilege('authenticated','public.settle_stripe_booking_invoice(jsonb)','execute'),'Portal roles cannot settle invoices');
select ok(not has_function_privilege('authenticated','public.claim_stripe_booking_invoice_effect(text)','execute'),'Portal roles cannot claim provider intents');
select ok(not has_table_privilege('service_role','workspace_internal.stripe_booking_invoice_receipts','select'),'Private receipt bodies are RPC-only');
insert into public.studios(id,name,slug) values('e7400000-0000-4000-8000-000000000001','E2E installment studio','e2e-installment-studio');
insert into public.students(id,studio_id,full_name,email) values('e7400000-0000-4000-8000-000000000002','e7400000-0000-4000-8000-000000000001','E2E installment learner','e2e-installment@example.test');
insert into public.booking_services(id,studio_id,slug,name,category,duration_minutes,price_minor) values('e7400000-0000-4000-8000-000000000003','e7400000-0000-4000-8000-000000000001','e2e-installments','E2E installment service','private',60,18001);
insert into public.bookings(id,studio_id,reference,service_id,student_id,guest_name,guest_email,starts_at,ends_at,timezone,location,status,payment_policy,payment_status,total_minor,paid_minor,currency,policy_snapshot,manage_token_hash,stripe_subscription_id,stripe_customer_id,installment_count,installments_paid,installment_remainder_minor)
values('e7400000-0000-4000-8000-000000000004','e7400000-0000-4000-8000-000000000001','E2E-INSTALLMENTS','e7400000-0000-4000-8000-000000000003','e7400000-0000-4000-8000-000000000002','E2E installment learner','e2e-installment@example.test','2031-11-10T18:00:00Z','2031-11-10T19:00:00Z','UTC','in_person','confirmed','installments','partially_paid',18001,6000,'USD','{}','e2e-installment-token','sub_e2e_installments','cus_e2e_installments',3,1,1);
create function pg_temp.installment_value(p_invoice text default 'in_e2e_second',p_amount bigint default 6000) returns jsonb language sql as $$
 select jsonb_build_object('bookingId','e7400000-0000-4000-8000-000000000004','invoiceId',p_invoice,'subscriptionId','sub_e2e_installments','customerId','cus_e2e_installments','amountMinor',p_amount,'currency','USD');
$$;
create function pg_temp.reject_installment_write() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_INSTALLMENT_FAILURE'; end$$;
create trigger e2e_installment_payment_fault before insert on public.payment_entries for each row when(new.external_reference='in_e2e_payment_fault') execute function pg_temp.reject_installment_write();
set local role service_role;
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_payment_fault'))$$,'P0001','SYNTHETIC_INSTALLMENT_FAILURE','Ledger rejection aborts booking mutation');
reset role;
select is((select paid_minor from public.bookings where id='e7400000-0000-4000-8000-000000000004'),6000::bigint,'Ledger failure leaves existing paid amount');
select is((select installments_paid from public.bookings where id='e7400000-0000-4000-8000-000000000004'),1,'Ledger failure leaves existing count');
drop trigger e2e_installment_payment_fault on public.payment_entries;
create trigger e2e_installment_intent_fault before insert on workspace_internal.stripe_booking_invoice_effects for each row execute function pg_temp.reject_installment_write();
set local role service_role;
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_intent_fault'))$$,'P0001','SYNTHETIC_INSTALLMENT_FAILURE','Durable intent rejection rolls back the entire financial transaction');
reset role;
drop trigger e2e_installment_intent_fault on workspace_internal.stripe_booking_invoice_effects;
select is((select count(*) from public.payment_entries where student_id='e7400000-0000-4000-8000-000000000002'),0::bigint,'Late intent failure leaves no payment');
select is((select count(*) from workspace_internal.stripe_booking_invoice_receipts where booking_id='e7400000-0000-4000-8000-000000000004'),0::bigint,'Late intent failure leaves no success receipt');
create trigger e2e_installment_audit_fault before insert on public.audit_events for each row when(new.correlation_id='in_e2e_audit_fault') execute function pg_temp.reject_installment_write();
set local role service_role;
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_audit_fault'))$$,'P0001','SYNTHETIC_INSTALLMENT_FAILURE','Audit rejection rolls back ledger and booking');
reset role;
drop trigger e2e_installment_audit_fault on public.audit_events;
set local role service_role;
select lives_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value())$$,'Signed service command settles the second installment');
select lives_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value())$$,'Identical invoice replays after a lost response');
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_second',6001))$$,'P0001','IDEMPOTENCY_CONFLICT','Changed amount cannot replay the invoice');
reset role;
select is((select paid_minor from public.bookings where id='e7400000-0000-4000-8000-000000000004'),12000::bigint,'Replay increments paid amount once');
select is((select installments_paid from public.bookings where id='e7400000-0000-4000-8000-000000000004'),2,'Replay increments installment count once');
select is((select count(*) from public.payment_entries where external_reference='in_e2e_second'),1::bigint,'Invoice has one append-only payment');
select is((select count(*) from public.audit_events where correlation_id='in_e2e_second'),1::bigint,'Invoice has one audit event');
select is((select rounding_minor from workspace_internal.stripe_booking_invoice_effects where invoice_id='in_e2e_second'),1::bigint,'Rounding intent is durable independently of provider delivery');
create temporary table e2e_installment_claim as select public.claim_stripe_booking_invoice_effect('in_e2e_second') value;
select is(public.claim_stripe_booking_invoice_effect('in_e2e_second')->>'status','running','Concurrent provider attempt cannot steal a current lease');
select is(public.finish_stripe_booking_invoice_effect('in_e2e_second',gen_random_uuid(),'rounding','ii_synthetic'),false,'Stale token cannot acknowledge provider work');
select is(public.finish_stripe_booking_invoice_effect('in_e2e_second',(select (value->>'claim_token')::uuid from e2e_installment_claim),'provider'),true,'Provider failure retains pending intent');
select is((select status from workspace_internal.stripe_booking_invoice_effects where invoice_id='in_e2e_second'),'pending','Failed provider work remains recoverable');
select is((select paid_minor from public.bookings where id='e7400000-0000-4000-8000-000000000004'),12000::bigint,'Provider failure does not roll back or repeat money');
truncate e2e_installment_claim;
insert into e2e_installment_claim select public.claim_stripe_booking_invoice_effect('in_e2e_second');
select is(public.finish_stripe_booking_invoice_effect('in_e2e_second',(select (value->>'claim_token')::uuid from e2e_installment_claim),'rounding','ii_synthetic'),true,'Current claim records the provider object');
select is(public.claim_stripe_booking_invoice_effect('in_e2e_second')->>'status','completed','Completed projection is reported truthfully');
insert into public.payment_entries(student_id,kind,amount_minor,currency,external_reference,reason) values('e7400000-0000-4000-8000-000000000002','payment',6000,'USD','in_e2e_legacy','Synthetic historical ledger');
insert into public.webhook_events(id,provider,event_type,payload,status,received_at) values('evt_e2e_legacy_partial','stripe','invoice.paid','{"data":{"object":{"id":"in_e2e_legacy_partial"}}}','failed',now()-interval '1 day');
set local role service_role;
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_legacy'))$$,'P0001','REVIEW_REQUIRED: Legacy invoice requires reconciled booking and ledger evidence.','Existing history is not incremented again without reconciliation');
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_legacy_partial'))$$,'P0001','REVIEW_REQUIRED: Legacy invoice requires reconciled booking and ledger evidence.','Pre-cutover partial delivery cannot be inferred from counters');
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_zero',0))$$,'P0001','REVIEW_REQUIRED: Zero-value installment needs agreement review.','A zero amount does not silently advance paid status');
select throws_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_wrong_customer')||'{"customerId":"cus_other"}'::jsonb)$$,'P0001','VALIDATION_FAILED: Invoice customer does not match the booking.','Payer/customer binding is checked in the database');
select lives_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_final',6001))$$,'Final positive invoice commits once');
reset role;
select is((select paid_minor from public.bookings where id='e7400000-0000-4000-8000-000000000004'),18001::bigint,'Final amount matches the agreement after rounding');
select is((select cancel_required from workspace_internal.stripe_booking_invoice_effects where invoice_id='in_e2e_final'),true,'Subscription cancellation is a separate durable intent');
-- Invoice can arrive before checkout.session.completed. Confirm first booking and
-- append its first invoice inside this same command, never twice.
insert into public.booking_holds(id,studio_id,service_id,starts_at,ends_at) values('e7400000-0000-4000-8000-000000000006','e7400000-0000-4000-8000-000000000001','e7400000-0000-4000-8000-000000000003','2031-11-11T18:00:00Z','2031-11-11T19:00:00Z');
insert into public.bookings(id,studio_id,reference,service_id,student_id,guest_name,guest_email,starts_at,ends_at,timezone,location,status,payment_policy,payment_status,total_minor,paid_minor,currency,policy_snapshot,manage_token_hash,installment_count,hold_ids)
values('e7400000-0000-4000-8000-000000000005','e7400000-0000-4000-8000-000000000001','E2E-INSTALLMENT-FIRST','e7400000-0000-4000-8000-000000000003','e7400000-0000-4000-8000-000000000002','E2E installment learner','e2e-installment@example.test','2031-11-11T18:00:00Z','2031-11-11T19:00:00Z','UTC','in_person','pending_payment','installments','processing',18000,0,'USD','{}','e2e-installment-first-token',3,array['e7400000-0000-4000-8000-000000000006'::uuid]);
set local role service_role;
select lives_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_first')||'{"bookingId":"e7400000-0000-4000-8000-000000000005","subscriptionId":"sub_e2e_first","holdId":"e7400000-0000-4000-8000-000000000006"}'::jsonb)$$,'Initial invoice confirms the booking, lesson and payment atomically');
select lives_ok($$select public.settle_stripe_booking_invoice(pg_temp.installment_value('in_e2e_first')||'{"bookingId":"e7400000-0000-4000-8000-000000000005","subscriptionId":"sub_e2e_first","holdId":"e7400000-0000-4000-8000-000000000006"}'::jsonb)$$,'First invoice replay does not repeat canonical confirmation');
reset role;
select is((select installments_paid from public.bookings where id='e7400000-0000-4000-8000-000000000005'),1,'First invoice advances count once');
select is((select paid_minor from public.bookings where id='e7400000-0000-4000-8000-000000000005'),6000::bigint,'First invoice is not double-counted');
select is((select count(*) from public.payment_entries where external_reference='in_e2e_first'),1::bigint,'First invoice has one payment');
select is((select count(*) from public.lesson_participants where booking_id='e7400000-0000-4000-8000-000000000005'),1::bigint,'First invoice has one participant');
select is((select notify_booking from workspace_internal.stripe_booking_invoice_effects where invoice_id='in_e2e_first'),'e7400000-0000-4000-8000-000000000005'::uuid,'Initial booking notification intent cannot be lost after commit');
select * from finish();
rollback;
